    const p = G.o[i];
    a.push(el("rect", { x:(p[0] - s*.44).toFixed(2), y:(p[1] - s*.44).toFixed(2),
      width:(s*.88).toFixed(2), height:(s*.88).toFixed(2), rx:(s*.1).toFixed(2),
      fill:mau, opacity:0 }, g));
